(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','Geography','World Regions, Water Bodies & Places','statement_based','medium','Consider the following countries:','{"statements": ["Azerbaijan", "Georgia", "Iran", "Uzbekistan"], "closing": "How many of the above countries have a coastline on the Caspian Sea?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only two -- Azerbaijan and Iran. The Caspian Sea is bordered by five countries: Russia, Kazakhstan, Turkmenistan, Iran and Azerbaijan. Georgia lies on the Black Sea coast, on the other side of the Caucasus. Uzbekistan is one of the world''s two doubly landlocked countries; the water body it shares with Kazakhstan is the Aral Sea, not the Caspian.','ugeo-caspian-littoral-states','original_pattern_matched','Encyclopaedia Britannica, ''Caspian Sea''; CIA World Factbook, country profiles of Georgia and Uzbekistan.','draft'),
('upsc','Geography','Climatology & Biomes','statement_based','medium','Consider the following statements about local winds:','{"statements": ["The Chinook is a warm, dry wind that blows down the eastern slopes of the Rocky Mountains.", "The Mistral is a cold wind that blows down the Rhone valley towards the Mediterranean.", "The Harmattan is a hot, humid wind that blows from the Atlantic onto the coast of West Africa.", "The Sirocco is a hot wind that blows from the Sahara towards southern Europe."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1, 2 and 4 are correct. The Chinook is a fohn-type wind: air warms as it descends the leeward (eastern) side of the Rockies, melting snow quickly, hence ''snow eater''. The Mistral is funnelled down the Rhone valley to the Gulf of Lion, and the Sirocco carries hot, dusty Saharan air across the Mediterranean. Statement 3 is wrong: the Harmattan is a dry, dusty north-easterly that blows from the Sahara over West Africa; its dryness is such a relief from the humid coast that it is called ''the doctor''.','ugeo-local-winds','original_pattern_matched','NCERT Geography Class XI, ''Fundamentals of Physical Geography'', ch. ''Atmospheric Circulation and Weather Systems'' (local winds); Encyclopaedia Britannica, ''Harmattan''.','draft'),
('upsc','Geography','Indian Physiography, Climate & Regions','statement_based','medium','Consider the following statements about the Western and Eastern Ghats:','{"statements": ["The Western Ghats are more continuous than the Eastern Ghats.", "The Western Ghats are generally lower in elevation than the Eastern Ghats.", "Anamudi, the highest peak of peninsular India, lies in the Western Ghats."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true, "numbering": "roman"}'::jsonb,'[{"id": "a", "body": "I and III only", "isCorrect": true}, {"id": "b", "body": "I and II only", "isCorrect": false}, {"id": "c", "body": "II and III only", "isCorrect": false}, {"id": "d", "body": "I, II and III", "isCorrect": false}]'::jsonb,2,0.66,'Statements I and III are correct. The Western Ghats run almost unbroken along the west coast and can be crossed only through passes such as the Thal, Bhor and Pal Ghats, whereas the Eastern Ghats are discontinuous, broken up by the Mahanadi, Godavari, Krishna and Kaveri. Anamudi (2,695 m) in the Anaimalai Hills of Kerala is the highest peak of peninsular India. Statement II is the reverse: the Western Ghats are higher (roughly 900-1,600 m on average) than the Eastern Ghats (roughly 600 m).','ugeo-western-eastern-ghats','original_pattern_matched','NCERT Geography Class XI, ''India: Physical Environment'', ch. ''Structure and Physiography'' (the Peninsular Plateau).','draft'),
('upsc','Geography','Indian Rivers, Lakes & Wetlands','statement_based','medium','Consider the following statements about the rivers of peninsular India:','{"statements": ["The Narmada and the Tapi flow westwards through rift valleys.", "The Mahanadi rises in Chhattisgarh and forms a delta in Odisha.", "The Godavari, the longest river of peninsular India, ends in an estuary rather than a delta."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "1 and 2", "isCorrect": true}, {"id": "c", "body": "2 and 3", "isCorrect": false}, {"id": "d", "body": "3 only", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Narmada and the Tapi are the two large west-flowing rivers of the Peninsula; they run through faulted rift valleys and end in estuaries, not deltas. The Mahanadi rises near Sihawa in Chhattisgarh and builds a delta on the Odisha coast. Statement 3 is wrong: the Godavari (about 1,465 km) is indeed the longest peninsular river, but like the other east-flowing rivers it forms a large delta on the Bay of Bengal.','ugeo-peninsular-river-mouths','original_pattern_matched','NCERT Geography Class XI, ''India: Physical Environment'', ch. ''Drainage System'' (the Peninsular drainage system).','draft'),
('upsc','Geography','Climatology & Biomes','mcq','medium','Which one of the following climate types has the largest annual range of temperature?','{}'::jsonb,'[{"id": "a", "body": "Equatorial rainforest climate", "isCorrect": false}, {"id": "b", "body": "Mediterranean climate", "isCorrect": false}, {"id": "c", "body": "Tropical savanna climate", "isCorrect": false}, {"id": "d", "body": "Sub-arctic continental (taiga) climate", "isCorrect": true}]'::jsonb,2,0.66,'The sub-arctic continental climate of Siberia and northern Canada, deep inside large landmasses, has the largest annual range on Earth: Verkhoyansk averages below -45 degrees Celsius in January and about +15 degrees in July, a range above 60 degrees. The equatorial climate has the smallest annual range (2-3 degrees), and the other two are moderated by latitude or by the sea.','ugeo-taiga-annual-range','original_pattern_matched','NCERT Geography Class XI, ''Fundamentals of Physical Geography'', ch. ''World Climate and Climate Change'' (Koppen''s classification).','draft')
